read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if read(p) == v["after"]:
        skipped += 1
    elif sha(p) == v["before"]:
        writes[p] = v["after"]
    else:
        abort(f"{p} is not the version this patch was written for; send its sha256")
for p, text in NEW.items():
    if os.path.exists(p):
        if read(p) == text:
            skipped += 1; continue
        abort(f"{p} already exists with different content")
    writes[p] = text
cl = read("CHANGELOG.md")
if CL_NEW in cl:
    skipped += 1
elif cl.count(CL_OLD) == 1:
    writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else:
    abort("CHANGELOG.md: the patch 12 entry this appends after was not found")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 13: {len(writes)} files written, {skipped} already in place.")
